/// <summary>
/// NDX Databaselog class sesigned by NDX
/// </summary>
final class NDXSysDataBaseLogItemStateClass extends NDXSysDataBaseLog
{
    NDXSysDataBaseLogItemStatus       lNDXSysDataBaseLogItemStatus;
}

Method.Source:
void deleteRecords(RecId _recIdInventTable)
{
    lNDXSysDataBaseLogItemStatus = null;

    if (_recIdInventTable)
    {
        delete_from lNDXSysDataBaseLogItemStatus where lNDXSysDataBaseLogItemStatus.InventTableRefRecId == _recIdInventTable;
    }
    else
    {
        delete_from lNDXSysDataBaseLogItemStatus;
    }
}

createdDateTime getLatest()
{
    select firstOnly DateTimeChanged from lNDXSysDataBaseLogItemStatus order by DateTimeChanged desc;
    return lNDXSysDataBaseLogItemStatus.DateTimeChanged;
}

void storeValues(InventTable _inventTable)
{
    lNDXSysDataBaseLogItemStatus.clear();
    lNDXSysDataBaseLogItemStatus.InventTableRefRecId  = _inventTable.RecId;
    lNDXSysDataBaseLogItemStatus.DateTimeChanged      = sysDatabaseLog.CreatedDateTime;
    lNDXSysDataBaseLogItemStatus.Username             = sysDatabaseLog.Username;
    lNDXSysDataBaseLogItemStatus.StateFrom   = conpeek(con, 3);
    lNDXSysDataBaseLogItemStatus.StateTo     = conpeek(con, 2);
    lNDXSysDataBaseLogItemStatus.insert();
    ++nAnz;
}
